responseFormat.typescriptTypesReference:
type Citation = {
commentId: number;
};

type Clause = {
text: string;
citations: Citation[];
};

type Sentence = {
clauses: Clause[];
};

type Paragraph = {
id: string;
title: string;
sentences: Sentence[];
};

type Subtask = {
id: string;
title: string;
paragraphs: Paragraph[];
};

polisAnalysisPrompt.example:
{
"id": "tribe_characteristics",
"title": "Tribe Characteristics",
"paragraphs": [
{
"id": "tribe_defining_characteristics",
"title": "What Defines This Tribe",
"sentences": [
{
"clauses": [
{
"text": "This tribe is most distinctively defined by their strong support for market-based solutions and skepticism toward regulatory intervention.",
"citations": [101, 145, 178]
},
{
"text": "Their most characteristic positions cluster around economic efficiency and individual choice, suggesting a worldview that prioritizes autonomy and competition.",
"citations": [132, 156, 204]
}
]
}
]
},
{
"id": "tribe_vs_others",
"title": "How This Tribe Differs From the Broader Population",
"sentences": [
{
"clauses": [
{
"text": "Compared to the overall population, this tribe is far more supportive of deregulation proposals and notably less sympathetic to calls for expanded public services.",
"citations": [145, 178, 221]
},
{
"text": "This divergence suggests fundamentally different assumptions about the role of institutions, with this tribe favoring decentralized and voluntary approaches where others prefer collective action.",
"citations": [204, 245]
}
]
}
]
}
]
}
